using System; using System.Collections.Generic; using System.Data; using Oracle.ManagedDataAccess.Client; using Interfaces;
namespace Server { public class RemoteOperation:MarshalByRefObject,IRemoteOperation {
 // MACHINE 2: change Oracle host, port, service and credentials for the exam.
 private const string oradb="Data Source=localhost:1522/XEPDB1; User Id=oracle; Password=manager;";
 public override object InitializeLifetimeService(){return null;} public string TesterConnexion(string nomClient){return "Bonjour "+nomClient;}
 private DataSet Query(string sql,Action<OracleCommand> bind=null){using(var c=new OracleConnection(oradb))using(var cmd=new OracleCommand(sql,c)){cmd.BindByName=true;if(bind!=null)bind(cmd);using(var da=new OracleDataAdapter(cmd)){var ds=new DataSet();da.Fill(ds,"Employes");return ds;}}}
 private int Execute(string sql,Action<OracleCommand> bind){using(var c=new OracleConnection(oradb))using(var cmd=new OracleCommand(sql,c)){cmd.BindByName=true;bind(cmd);c.Open();return cmd.ExecuteNonQuery();}}
 private static void VerifierTexte(string s,int max){if(string.IsNullOrWhiteSpace(s)||s.Trim().Length>max)throw new ArgumentException("Champ obligatoire ou trop long.");}
 private static void VerifierSalaire(decimal s){if(s<0||s>9999999999.99m)throw new ArgumentException("Salaire invalide.");}
 private static object Telephone(string t){if(t!=null&&t.Trim().Length>20)throw new ArgumentException("Téléphone trop long.");return string.IsNullOrWhiteSpace(t)?(object)DBNull.Value:t.Trim();}
 public DataSet GetEmployes(){return Query("SELECT * FROM EmployeModification ORDER BY matricule");}
 public DataSet RechercherEmploye(int matricule){return Query("SELECT * FROM EmployeModification WHERE matricule=:matricule",c=>c.Parameters.Add("matricule",OracleDbType.Int32).Value=matricule);}
 private int Sauver(int m,string n,string p,string d,string t,decimal s,bool update){VerifierTexte(n,30);VerifierTexte(p,30);VerifierTexte(d,40);VerifierSalaire(s);object tel=Telephone(t);string sql=update?"UPDATE EmployeModification SET nom=:nom,prenom=:prenom,departement=:departement,telephone=:telephone,salaire=:salaire WHERE matricule=:matricule":"INSERT INTO EmployeModification(matricule,nom,prenom,departement,telephone,salaire) VALUES(:matricule,:nom,:prenom,:departement,:telephone,:salaire)";return Execute(sql,c=>{c.Parameters.Add("matricule",OracleDbType.Int32).Value=m;c.Parameters.Add("nom",OracleDbType.Varchar2).Value=n.Trim();c.Parameters.Add("prenom",OracleDbType.Varchar2).Value=p.Trim();c.Parameters.Add("departement",OracleDbType.Varchar2).Value=d.Trim();c.Parameters.Add("telephone",OracleDbType.Varchar2).Value=tel;c.Parameters.Add("salaire",OracleDbType.Decimal).Value=s;});}
 public int AjouterEmploye(int m,string n,string p,string d,string t,decimal s){return Sauver(m,n,p,d,t,s,false);} public int ModifierEmploye(int m,string n,string p,string d,string t,decimal s){return Sauver(m,n,p,d,t,s,true);}
 public int SupprimerEmploye(int matricule){return Execute("DELETE FROM EmployeModification WHERE matricule=:matricule",c=>c.Parameters.Add("matricule",OracleDbType.Int32).Value=matricule);}
 // TRICK 13: only columns in SET change; the primary key in WHERE selects one employee.
 public int ModifierSalaire(int matricule,decimal salaire){VerifierSalaire(salaire);return Execute("UPDATE EmployeModification SET salaire=:salaire WHERE matricule=:matricule",c=>{c.Parameters.Add("salaire",OracleDbType.Decimal).Value=salaire;c.Parameters.Add("matricule",OracleDbType.Int32).Value=matricule;});}
 public int ModifierDepartement(int matricule,string departement){VerifierTexte(departement,40);return Execute("UPDATE EmployeModification SET departement=:departement WHERE matricule=:matricule",c=>{c.Parameters.Add("departement",OracleDbType.Varchar2).Value=departement.Trim();c.Parameters.Add("matricule",OracleDbType.Int32).Value=matricule;});}
 public int ModifierTelephone(int matricule,string telephone){object tel=Telephone(telephone);return Execute("UPDATE EmployeModification SET telephone=:telephone WHERE matricule=:matricule",c=>{c.Parameters.Add("telephone",OracleDbType.Varchar2).Value=tel;c.Parameters.Add("matricule",OracleDbType.Int32).Value=matricule;});}
 // Only fixed fragments enter SQL; bind and validate only selected fields. Blank selected telephone means NULL.
 public int ModifierEmployePartiellement(int matricule,bool changerSalaire,decimal salaire,bool changerDepartement,string departement,bool changerTelephone,string telephone){var clauses=new List<string>();object tel=DBNull.Value;if(changerSalaire){VerifierSalaire(salaire);clauses.Add("salaire=:salaire");}if(changerDepartement){VerifierTexte(departement,40);clauses.Add("departement=:departement");}if(changerTelephone){tel=Telephone(telephone);clauses.Add("telephone=:telephone");}if(clauses.Count==0)throw new ArgumentException("Aucun champ à modifier.");string sql="UPDATE EmployeModification SET "+string.Join(", ",clauses)+" WHERE matricule=:matricule";return Execute(sql,c=>{c.Parameters.Add("matricule",OracleDbType.Int32).Value=matricule;if(changerSalaire)c.Parameters.Add("salaire",OracleDbType.Decimal).Value=salaire;if(changerDepartement)c.Parameters.Add("departement",OracleDbType.Varchar2).Value=departement.Trim();if(changerTelephone)c.Parameters.Add("telephone",OracleDbType.Varchar2).Value=tel;});}
} }
